  const query=search.trim(), isCode=codePattern.test(query), isQr=qrPattern.test(query);
  const members=useListStaffMembers({q:query||undefined},{query:{enabled:query.length>=2&&!isCode&&!isQr,queryKey:getListStaffMembersQueryKey({q:query})}});
  const found=useFindMember({code:isCode?query:undefined,qr_token:isQr?query:undefined},{query:{enabled:isCode||isQr,queryKey:getFindMemberQueryKey({code:isCode?query:undefined,qr_token:isQr?query:undefined})}});
  const card=member ?? (isCode||isQr ? found.data ?? null : null);
