function OwnerMemberForm({onSubmit}:{onSubmit:(d:{name:string;member_code:string;phone:string;nickname:string})=>void}){const [name,SN]=useState(''),[code,SC]=useState(''),[phone,SP]=useState(''),[nick,SK]=useState('');return <form className="grid gap-3" onSubmit={e=>{e.preventDefault();if(name.trim()&&codePattern.test(code)&&/^\d{9,20}$/.test(phone)&&nick.trim().length>=2)onSubmit({name:name.trim(),member_code:code,phone,nickname:nick.trim()});}}><div><Label>ชื่อ</Label><Input value={name} onChange={e=>SN(e.target.value)} data-testid="input-new-member-name"/></div><div><Label>รหัสสมาชิก</Label><Input value={code} onChange={e=>SC(e.target.value)} data-testid="input-new-member-code"/></div><div><Label>เบอร์โทร</Label><Input value={phone} onChange={e=>SP(e.target.value)} data-testid="input-new-member-phone"/></div><div><Label>ชื่อเล่น</Label><Input value={nick} onChange={e=>SK(e.target.value)} data-testid="input-new-member-nickname"/></div><Button data-testid="button-create-owner-member">สร้างสมาชิก</Button></form>}
