function BankForm({onSubmit}:{onSubmit:(d:{bank_name:string;account_number:string;account_holder:string;daily_limit:string})=>void}){const[b,SB]=useState(''),[n,SN]=useState(''),[h,SH]=useState(''),[l,SL]=useState('0');return <form className="grid gap-3" onSubmit={e=>{e.preventDefault();if(b.trim()&&/^[0-9 -]{6,24}$/.test(n)&&h.trim()&&/^\d+(\.\d{1,2})?$/.test(l))onSubmit({bank_name:b.trim(),account_number:n.replaceAll(' ',''),account_holder:h.trim(),daily_limit:l});}}><Label>ธนาคาร</Label><Input value={b} onChange={e=>SB(e.target.value)}/><Label>เลขบัญชี</Label><Input inputMode="numeric" value={n} onChange={e=>SN(e.target.value)}/><Label>ชื่อบัญชี</Label><Input value={h} onChange={e=>SH(e.target.value)}/><Label>วงเงินต่อวัน</Label><Input inputMode="decimal" value={l} onChange={e=>SL(e.target.value)}/><Button data-testid="button-create-bank-account">เพิ่มบัญชี</Button></form>}
