function OwnerPins({onSubmit}:{onSubmit:(d:{owner_pin?:string;staff_pin?:string})=>void}){const[o,SO]=useState(''),[s,SS]=useState('');return <form className="grid gap-3" onSubmit={e=>{e.preventDefault();const d:{owner_pin?:string;staff_pin?:string}={};if(/^\d{6,12}$/.test(o))d.owner_pin=o;if(/^\d{4,12}$/.test(s))d.staff_pin=s;if(Object.keys(d).length)onSubmit(d);}}><Label>PIN เจ้าของใหม่ (6–12 หลัก)</Label><Input type="password" inputMode="numeric" autoComplete="new-password" value={o} onChange={e=>SO(e.target.value.replace(/\D/g,''))} data-testid="input-owner-pin"/><Label>PIN พนักงานใหม่ (4–12 หลัก)</Label><Input type="password" inputMode="numeric" autoComplete="new-password" value={s} onChange={e=>SS(e.target.value.replace(/\D/g,''))} data-testid="input-owner-staff-pin"/><Button data-testid="button-save-owner-pins">บันทึก PIN</Button></form>}

function Router(){const[loc]=useLocation();return <ErrorBoundary resetKey={loc}><RouteSwitch>
  <Route path="/" component={Home}/><Route path="/staff" component={StaffRoute}/><Route path="/owner" component={OwnerRoute}/><Route path="/admin">{()=>{const desk=new URLSearchParams(window.location.search).get('desk');return desk==='staff'?<StaffRoute/>:<OwnerRoute/>;}}</Route><Route component={()=><Home/>}/></RouteSwitch></ErrorBoundary>}
function OperationErrors(){const[message,setMessage]=useState('');useEffect(()=>{const listener=(event:Event)=>setMessage((event as CustomEvent<string>).detail);window.addEventListener('jaguar-operation-error',listener);return()=>window.removeEventListener('jaguar-operation-error',listener);},[]);return message?<div role="alert" aria-live="assertive" className="fixed bottom-4 left-4 right-4 z-50 mx-auto flex max-w-xl items-center justify-between gap-3 rounded-md border border-destructive bg-card p-4 text-sm shadow-lg" data-testid="operation-error"><span>ทำรายการไม่สำเร็จ: {message}</span><Button variant="outline" size="sm" onClick={()=>setMessage('')} data-testid="button-dismiss-error">ปิด</Button></div>:null}
function App(){useEffect(()=>{document.documentElement.setAttribute('data-brand-theme','2026');},[]);return <QueryClientProvider client={qc}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,'')}><Router/></WouterRouter><OperationErrors/><Toaster/></TooltipProvider></QueryClientProvider>}
export default App;
